"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[22144],{28453:(e,n,t)=>{t.d(n,{R:()=>s,x:()=>r});var o=t(96540);const i={},a=o.createContext(i);function s(e){const n=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:n},e.children)}},50750:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>o,toc:()=>h});const o=JSON.parse('{"id":"qiangguo/hexinproblemandsolution","title":"","description":"He Xin\'s illness, in a certain sense, is not his alone but is a shared malady of the era and of all sentient beings. Whether He Xin or his opponents, the root of their illness is actually the same. Of course, the specific symptoms vary, which is why there are so-called arguments. Setting aside the root cause for now, let us first discuss He Xin\'s old symptom of Hegelian confusion. The kind of Hegelian nonsense about the unity of history and logic, after being picked up by Lenin and standardized by Stalin, has already insidiously polluted the minds of the world for generations. It is no surprise that He Xin has been infected. He Xin fancies himself an expert on Old Marx, but in reality he hasn\'t even touched Old Marx\'s skin. Due to historical reasons, the tremendous importance of Feuerbach\'s comprehensive reckoning with Hegel, and Engels\' expression of this reckoning\'s significance in \\"Ludwig Feuerbach and the End of Classical German Philosophy,\\" have been overlooked. Without Feuerbach there would be no Old Marx. Feuerbach is the true beginning of the great philosophical turn (not to mention that Kant was the precursor). Just look at how bashful Heidegger appears, and you can better appreciate Feuerbach\'s significance. Starting from Feuerbach, all God-like divine and ontological hypotheses became jokes. Old Marx used Feuerbach\'s concept of alienation to write his famous manuscripts, and then suddenly one day, Old Marx discovered that Feuerbach\'s \\"man,\\" \\"species-being,\\" and \\"alienation\\" were equally a joke. He abandoned these, abandoned all illusions, and for the first time stood on the ground of reality, facing real people, facing the real relations between humans and between humans and nature. Green mountains everywhere, bodhi wherever the eye falls -- Old Marx began to become Old Marx. Therefore, to cure He Xin and others of this Hegelian common illness, Feuerbach is excellent medicine. Anyone who attempts to bypass Feuerbach and go straight from Hegel to Old Marx is undoubtedly a fool dreaming.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/hexinproblemandsolution.md","sourceDirName":"qiangguo","slug":"/qiangguo/hexinproblemandsolution","permalink":"/en/qiangguo/hexinproblemandsolution","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"hexinproblemandsolution","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u4f55\u65b0\uff0c\u4e0d\u8981\u4ee5\u8001\u5356\u8001\uff0c\u4ee5\u65e0\u77e5\u5356\u65e0\u77e5\uff01","permalink":"/en/qiangguo/oldforold"},"next":{"title":"\u4f55\u65b0\u5148\u751f\uff0c\u65b0\u56fd\u5bb6\u4e3b\u4e49\uff0c\u4f55\u65b0\u4e4b\u6709\uff1f","permalink":"/en/qiangguo/newnationalism"}}');var i=t(74848),a=t(28453);const s={id:"hexinproblemandsolution",title:"",hide_table_of_contents:!0},r='He Xin\'s "Illness" and the Corresponding "Medicine" (A Serious Discussion -- Please Let It Through)',l={},h=[];function d(e){const n={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"he-xins-illness-and-the-corresponding-medicine-a-serious-discussion----please-let-it-through",children:'He Xin\'s "Illness" and the Corresponding "Medicine" (A Serious Discussion -- Please Let It Through)'})}),"\n",(0,i.jsx)(n.p,{children:"He Xin's illness, in a certain sense, is not his alone but is a shared malady of the era and of all sentient beings. Whether He Xin or his opponents, the root of their illness is actually the same. Of course, the specific symptoms vary, which is why there are so-called arguments. Setting aside the root cause for now, let us first discuss He Xin's old symptom of Hegelian confusion. The kind of Hegelian nonsense about the unity of history and logic, after being picked up by Lenin and standardized by Stalin, has already insidiously polluted the minds of the world for generations. It is no surprise that He Xin has been infected. He Xin fancies himself an expert on Old Marx, but in reality he hasn't even touched Old Marx's skin. Due to historical reasons, the tremendous importance of Feuerbach's comprehensive reckoning with Hegel, and Engels' expression of this reckoning's significance in \"Ludwig Feuerbach and the End of Classical German Philosophy,\" have been overlooked. Without Feuerbach there would be no Old Marx. Feuerbach is the true beginning of the great philosophical turn (not to mention that Kant was the precursor). Just look at how bashful Heidegger appears, and you can better appreciate Feuerbach's significance. Starting from Feuerbach, all God-like divine and ontological hypotheses became jokes. Old Marx used Feuerbach's concept of alienation to write his famous manuscripts, and then suddenly one day, Old Marx discovered that Feuerbach's \"man,\" \"species-being,\" and \"alienation\" were equally a joke. He abandoned these, abandoned all illusions, and for the first time stood on the ground of reality, facing real people, facing the real relations between humans and between humans and nature. Green mountains everywhere, bodhi wherever the eye falls -- Old Marx began to become Old Marx. Therefore, to cure He Xin and others of this Hegelian common illness, Feuerbach is excellent medicine. Anyone who attempts to bypass Feuerbach and go straight from Hegel to Old Marx is undoubtedly a fool dreaming."}),"\n",(0,i.jsx)(n.p,{children:"As for He Xin's Buddhist views, he has fallen even deeper into the trap of interpreting Buddhism through Laozi and Zhuangzi, unable to free himself. A single word of wild fox Chan already carries karmic consequences -- how can one take this lightly? I suggest He Xin first study the Jiashan koan, cast off his deluded knowledge and views. When the time is ripe, there may yet be a chance for liberation. Otherwise, the sea of suffering is boundless -- how could there be any lucky escape?"})]})}function c(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);